"use strict";(self.webpackChunkmi_sitio=self.webpackChunkmi_sitio||[]).push([["50"],{5255(e,a,n){n.r(a),n.d(a,{metadata:()=>o,default:()=>u,frontMatter:()=>s,contentTitle:()=>t,toc:()=>d,assets:()=>l});var o=JSON.parse('{"id":"propuesta/elevator-pitch","title":"Elevator Pitch","description":"A continuaci\xf3n se presentan los 6 roles y enfoques t\xe9cnicos evaluados, incluyendo el enlace al video de la presentaci\xf3n y la transcripci\xf3n oficial del guion de cada integrante.","source":"@site/docs/03-propuesta/elevator-pitch.md","sourceDirName":"03-propuesta","slug":"/propuesta/elevator-pitch","permalink":"/CA_2S26_G5/docs/propuesta/elevator-pitch","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3},"sidebar":"tutorialSidebar","previous":{"title":"Documento Postmortem","permalink":"/CA_2S26_G5/docs/propuesta/documento-postmortem"},"next":{"title":"Flujo de la Soluci\xf3n","permalink":"/CA_2S26_G5/docs/propuesta/flujo-solucion"}}'),r=n(4848),i=n(8453);let s={sidebar_position:3},t="Elevator Pitch",l={},d=[{value:"Integrante 1 \u2014 Martin Emanuel Jolomocox Jeataz",id:"integrante-1--martin-emanuel-jolomocox-jeataz",level:2},{value:"Integrante 2 \u2014 David Eduardo Zamora Rodas",id:"integrante-2--david-eduardo-zamora-rodas",level:2},{value:"Integrante 3 \u2014 Beverlhy Esmeralda Contreras Silvestre",id:"integrante-3--beverlhy-esmeralda-contreras-silvestre",level:2},{value:"Integrante 4 \u2014 Victoria Yannaret Garc\xeda G\xf3mez",id:"integrante-4--victoria-yannaret-garc\xeda-g\xf3mez",level:2},{value:"Integrante 5 \u2014 Mario Alejandro Mendoza Ajquill",id:"integrante-5--mario-alejandro-mendoza-ajquill",level:2},{value:"Integrante 6 \u2014 Nicolas Esteban Ordo\xf1ez Ostuma",id:"integrante-6--nicolas-esteban-ordo\xf1ez-ostuma",level:2}];function c(e){let a={a:"a",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"elevator-pitch",children:"Elevator Pitch"})}),"\n",(0,r.jsx)(a.h1,{id:"registro-de-elevator-pitches---proyecto-2",children:"Registro de Elevator Pitches - Proyecto 2"}),"\n",(0,r.jsx)(a.p,{children:"A continuaci\xf3n se presentan los 6 roles y enfoques t\xe9cnicos evaluados, incluyendo el enlace al video de la presentaci\xf3n y la transcripci\xf3n oficial del guion de cada integrante."}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h2,{id:"integrante-1--martin-emanuel-jolomocox-jeataz",children:"Integrante 1 \u2014 Martin Emanuel Jolomocox Jeataz"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["Enlace al Video: ",(0,r.jsx)(a.a,{href:"https://youtu.be/NucKlScxzRE?si=yymm_iyGzd4Bld9e",children:"https://youtu.be/NucKlScxzRE?si=yymm_iyGzd4Bld9e"})]}),"\n",(0,r.jsxs)(a.li,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"}),"\r\nBuenos d\xedas. Quiero empezar con un dato que nos sorprendi\xf3 durante la entrevista: una libra de carne deber\xeda rendir exactamente 3.2 porciones para que el negocio gane . Pero nadie lo est\xe1 midiendo. Solo lo miden al ojo. El due\xf1o no pierde por vender poco, pierde por no saber cu\xe1nto est\xe1 sirviendo realmente."]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Para cerrar esa mala practica tengo pensado proponer  un M\xf3dulo de Estandarizaci\xf3n de Recetas y Descuento Autom\xe1tico por Porci\xf3n. Funciona as\xed: cada platillo que se vende en el punto de venta est\xe1 ligado a una receta est\xe1ndar. En el momento en que se registra un pedido, el sistema descuenta autom\xe1ticamente la fracci\xf3n exacta de libra o insumo que se us\xf3. As\xed, el due\xf1o puede comparar, en tiempo real, cu\xe1nto vendi\xf3 contra cu\xe1nta materia prima consumi\xf3 de verdad."}),"\n",(0,r.jsx)(a.p,{children:"El resultado es control total. Garantizamos que cada libra rinda el 100% de las porciones planificadas. Se acaban las variaciones al servir, se protegen las ganancias de  cada platillo y se elimina esas malas practicas de no calcular cuanto servir en cada platillo.  Ya no se trata de estimar: se trata de saber exactamente cu\xe1nto se sirve y cu\xe1nto se gana."}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h2,{id:"integrante-2--david-eduardo-zamora-rodas",children:"Integrante 2 \u2014 David Eduardo Zamora Rodas"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["Enlace al Video: ",(0,r.jsx)(a.a,{href:"https://youtu.be/N5aJ4u1LLDQ?si=OgTeXkNR7kitjrMT",children:"https://youtu.be/N5aJ4u1LLDQ?si=OgTeXkNR7kitjrMT"})]}),"\n",(0,r.jsxs)(a.li,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"}),"\r\nHola. Uno de los mayores problemas detectados en negocios de comida r\xe1pida como las taquer\xedas o puestos de panes es el manejo de la memoria humana durante la hora pico. Cuando hay decenas de clientes pidiendo al mismo tiempo, las variaciones como 'sin cebolla', 'extra salsa' o 'sin picante' suelen olvidarse o confundirse en la cocina. \xbfEl resultado? Platos devueltos, clientes insatisfechos y comida que termina directo en la basura."]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Para eliminar este problema, desarrollamos el M\xf3dulo de Modificadores Din\xe1micos e Integraci\xf3n con Pantalla de Cocina (KDS). Al momento de ingresar la orden en caja, despliega botones de modificaci\xf3n r\xe1pida que fuerzan la especificaci\xf3n exacta del producto. Esta informaci\xf3n viaja en tiempo real a la pantalla de preparaci\xf3n o impresora de cocina, mostrando de forma visual y clara cada instrucci\xf3n especial antes de ensamblar el plato."}),"\n",(0,r.jsx)(a.p,{children:"El impacto es doble: en primer lugar, reducimos a cero los errores de preparaci\xf3n derivados de la memoria del personal. En segundo lugar, recortamos hasta un 15% las mermas diarias por devoluciones y platillos desperdiciados. Adem\xe1s, protegemos la reputaci\xf3n del negocio al entregar exactamente lo que el cliente pidi\xf3 desde el primer intento."}),"\n",(0,r.jsx)(a.p,{children:"En el negocio de la comida, la precisi\xf3n es tan importante como la velocidad. Con nuestro m\xf3dulo de modificadores, aseguramos la satisfacci\xf3n total del cliente y eliminamos la p\xe9rdida silenciosa de ingredientes por errores de preparaci\xf3n. Esto es todo muchas gracias."}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h2,{id:"integrante-3--beverlhy-esmeralda-contreras-silvestre",children:"Integrante 3 \u2014 Beverlhy Esmeralda Contreras Silvestre"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["Enlace al video: ",(0,r.jsx)(a.a,{href:"https://youtu.be/wT0b2pkocBc?si=mx9cIlMiyX5JBe6D",children:"https://youtu.be/wT0b2pkocBc?si=mx9cIlMiyX5JBe6D"})]}),"\n",(0,r.jsxs)(a.li,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"}),"\r\nBuenas noches\r\nDurante nuestra visita a su negocio, pudimos identificar un problema que puede darse especialmente durante las horas de mayor movimiento: c\xf3mo atender a varios clientes sin que se formen filas largas o se cometan errores al tomar los pedidos."]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Cuando varios clientes llegan al mismo tiempo, tomar las \xf3rdenes en una libreta o tener que memorizarlas puede hacer que la atenci\xf3n sea m\xe1s lenta. Esto no solo afecta a los clientes, sino que tambi\xe9n puede provocar que varios de ellos prefieran irse sin haber comprado."}),"\n",(0,r.jsxs)(a.p,{children:["Por eso, el d\xeda de hoy les traigo una propuesta: implementar un ",(0,r.jsx)(a.strong,{children:"M\xf3dulo POS y Comandero Digital"}),", un sistema que permite registrar las ventas y organizar los pedidos de una manera m\xe1s r\xe1pida y sencilla."]}),"\n",(0,r.jsx)(a.p,{children:"Se preguntar\xe1n: \xbfc\xf3mo funciona?"}),"\n",(0,r.jsx)(a.p,{children:"El encargado de atender podr\xeda seleccionar los productos que el cliente desea desde una computadora, una tablet o un celular. El sistema registrar\xeda la venta autom\xe1ticamente y enviar\xeda el pedido al \xe1rea de cocina, evitando tener que anotarlo en papel o ir personalmente a comunicarlo. Adem\xe1s, los productos m\xe1s vendidos podr\xedan tener una opci\xf3n de acceso r\xe1pido para facilitar el trabajo."}),"\n",(0,r.jsx)(a.p,{children:"\xbfY en qu\xe9 beneficiar\xeda esto a su negocio?"}),"\n",(0,r.jsx)(a.p,{children:"Principalmente, ayudar\xeda a reducir las confusiones en los pedidos y a mantener la agilidad de la atenci\xf3n durante las horas pico. As\xed, sus empleados podr\xedan atender a m\xe1s personas de manera organizada y los clientes tendr\xedan que esperar menos."}),"\n",(0,r.jsx)(a.p,{children:"La idea no es complicar el trabajo con tecnolog\xeda, sino ofrecer una herramienta pr\xe1ctica que facilite las tareas diarias y permita aprovechar mejor cada oportunidad de venta."}),"\n",(0,r.jsx)(a.p,{children:"En conclusi\xf3n, con el M\xf3dulo POS y Comandero Digital buscamos que su negocio pueda atender de forma m\xe1s r\xe1pida, organizada y eficiente, beneficiando tanto a sus empleados como a sus clientes."}),"\n",(0,r.jsx)(a.p,{children:"Muchas gracias."}),"\n",(0,r.jsx)(a.h2,{id:"integrante-4--victoria-yannaret-garc\xeda-g\xf3mez",children:"Integrante 4 \u2014 Victoria Yannaret Garc\xeda G\xf3mez"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["Enlace al Video: ",(0,r.jsx)(a.a,{href:"https://www.youtube.com/watch?v=ufDDvTvHjNQ",children:"https://www.youtube.com/watch?v=ufDDvTvHjNQ"})]}),"\n",(0,r.jsxs)(a.li,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"})," Integrante n\xfamero cuatro, mi nombre es Victoria Yanaret Garc\xeda G\xf3mez, mi carnet es 202502718 y mi rol fue ser especialista en gesti\xf3n de inventarios y cadenas de suministro. Mi tema es el control de stock y alertas de reabastecimiento."]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Buen d\xeda. Quiero empezar planteando este escenario: estamos en la hora del almuerzo, hay una fila de 15 estudiantes esperando, el negocio est\xe1 lleno y de repente el cocinero se da cuenta de que se acabaron ingredientes como el aguacate, el pan o las tortillas. El comerciante tiene que salir corriendo a comprar a la tienda m\xe1s cercana, perdiendo tiempo, ventas y haciendo esperar al cliente. Quedarse sin ingredientes a mitad del turno es una de las fallas operativas m\xe1s costosas para un negocio."}),"\n",(0,r.jsx)(a.p,{children:"Para evitar esto, dise\xf1amos un modelo de gesti\xf3n de inventarios con alertas de stock m\xednimo. El sistema revisa todo el tiempo cu\xe1nta existencia queda de los insumos, tanto de los perecederos como de los secos. Cuando el inventario de un ingrediente cae por debajo del l\xedmite de seguridad que se configur\xf3 antes, la plataforma le manda una notificaci\xf3n autom\xe1tica a la pantalla o al tel\xe9fono del encargado para programar la compra antes de que el producto se termine."}),"\n",(0,r.jsx)(a.p,{children:'Con esto eliminamos al 100% las interrupciones en el servicio por falta de insumos. Adem\xe1s, mejoramos la compra de ingredientes perecederos, evitando que el negocio se quede sin producto de la nada o que se pierda dinero por comida que se vence o se arruina en la bodega por comprar de m\xe1s. Un negocio eficiente nunca le dice a un cliente "No le puedo vender porque nos quedamos sin ingredientes". Nuestro m\xf3dulo garantiza que la cocina funcione de corrido y siempre lista para atender en las horas pico. Muchas gracias.'}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h2,{id:"integrante-5--mario-alejandro-mendoza-ajquill",children:"Integrante 5 \u2014 Mario Alejandro Mendoza Ajquill"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["Enlace al Video: ",(0,r.jsx)(a.a,{href:"https://youtu.be/mVxPdr1MrbQ?si=0Omf51sbUgpcymbI",children:"https://youtu.be/mVxPdr1MrbQ?si=0Omf51sbUgpcymbI"})]}),"\n",(0,r.jsxs)(a.li,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"}),"\r\nAl finalizar una larga jornada de trabajo, lo \xfaltimo que quiere el due\xf1o de un negocio es pasar dos horas contando tickets en papel, haciendo cuentas en libretas o cuadrando la caja a ciegas. Muchos comerciantes ni siquiera saben con certeza cu\xe1nto ganaron en el d\xeda, cu\xe1l fue su producto m\xe1s vendido o si alcanzaron su meta b\xe1sica de ventas, como las 50 porciones diarias que identificamos en nuestras entrevistas de campo."]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Para transformar esta realidad, desarrollamos el M\xf3dulo de Dashboard de Ventas y Anal\xedtica en Tiempo Real. A trav\xe9s de un panel visual accesible desde cualquier smartphone o computadora, el due\xf1o puede monitorear las ventas minuto a minuto, ver gr\xe1ficos de los platillos m\xe1s populares y consultar el porcentaje de cumplimiento de su meta diaria sin mover un solo papel"}),"\n",(0,r.jsx)(a.p,{children:"El beneficio es instant\xe1neo: reducimos el tiempo del cierre de caja de 2 horas a menos de 5 minutos, totalmente automatizado. Adem\xe1s, el comerciante obtiene datos claros para tomar decisiones inteligentes: sabe exactamente qu\xe9 d\xedas vender m\xe1s, qu\xe9 productos promocionar y c\xf3mo planificar las compras de la semana con base en tendencias reales."}),"\n",(0,r.jsx)(a.p,{children:"Lo que no se mide, no se puede mejorar. Nuestro m\xf3dulo le devuelve tiempo de vida al comerciante y le entrega el control absoluto de las finanzas de su negocio al alcance de un clic. \xa1Muchas gracias"}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h2,{id:"integrante-6--nicolas-esteban-ordo\xf1ez-ostuma",children:"Integrante 6 \u2014 Nicolas Esteban Ordo\xf1ez Ostuma"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:["Enlace al Video:",(0,r.jsx)(a.a,{href:"https://youtu.be/ICltcAPLgzw?si=Lx96x2QKjFlNfnnd",children:"https://youtu.be/ICltcAPLgzw?si=Lx96x2QKjFlNfnnd"})]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Transcripci\xf3n del Guion:"}),"\r\n\xa1Hola a todos! Para concluir nuestra propuesta, debemos abordar la mayor preocupaci\xf3n de cualquier propietario de negocio: la seguridad de su dinero y la sostenibilidad de su inversi\xf3n. En las entrevistas descubrimos historias de p\xe9rdidas financieras por robos hormiga, descuadres no explicados en caja y el temor a que la implementaci\xf3n de un sistema inform\xe1tico sea demasiado costosa, compleja o dif\xedcil de mantener."]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Nuestra plataforma fue dise\xf1ada bajo una arquitectura web y m\xf3vil ligera en la nube, con un s\xf3lido sistema de Control de Accesos Basado en Roles (RBAC) y registros de auditor\xeda inmutables. Cada anulaci\xf3n de pedido, descuento o apertura de caj\xf3n de dinero queda registrado con hora, usuario y motivo exacto, evitando cualquier intento de manipulaci\xf3n sin autorizaci\xf3n del due\xf1o."}),"\n",(0,r.jsx)(a.p,{children:"El impacto econ\xf3mico es contundente: eliminamos las fugas silenciosas de dinero por mala administraci\xf3n y garantizamos un Retorno de Inversi\xf3n (ROI) proyectado a menos de 3 meses. Gracias al uso de tecnolog\xedas web est\xe1ndar y bajo consumo de recursos, el comercio no necesita invertir en servidores caros; puede operar directamente desde sus dispositivos actuales."}),"\n",(0,r.jsx)(a.p,{children:"Un software de gesti\xf3n no es un gasto, es una herramienta de protecci\xf3n y crecimiento. Con nuestra propuesta integral, transformamos comercios tradicionales en operaciones eficientes, seguras y altamente rentables. \xa1Muchas gracias!"})]})}function u(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},8453(e,a,n){n.d(a,{R:()=>s,x:()=>t});var o=n(6540);let r={},i=o.createContext(r);function s(e){let a=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),o.createElement(i.Provider,{value:a},e.children)}}}]);